import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, getJob, rowToJob } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string, fields?: { field: string; message: string }[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
async function readBody(req: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = []; let size = 0;
  for await (const chunk of req) {
    const b = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk); size += b.length;
    if (size > 1024 * 1024) throw new Error('body too large');
    chunks.push(b);
  }
  return Buffer.concat(chunks).toString('utf8');
}
function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

const server = createServer(async (req, res) => {
  const pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
  const known = pathname === '/' || pathname === '/health' || pathname === '/api/jobs' || /^\/api\/jobs\/[^/]+$/.test(pathname);
  if (!known) return error(res, 404, 'not_found', 'Route not found.');
  if (pathname === '/' && req.method === 'GET') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/health' && req.method === 'GET') {
    const beat = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE singleton = 1').get() as { seen_at: number } | undefined;
    return send(res, 200, { status: 'ok', worker: beat && Date.now() - beat.seen_at < 3000 ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs' && req.method === 'GET') {
    const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as Record<string, unknown>[];
    return send(res, 200, { jobs: rows.map(rowToJob) });
  }
  if (pathname === '/api/jobs' && req.method === 'POST') {
    const fields: { field: string; message: string }[] = [];
    const contentType = req.headers['content-type'] ?? '';
    if (!/^application\/json(?:\s*;|\s*$)/i.test(contentType)) fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
    let body: unknown;
    try { body = JSON.parse(await readBody(req)); } catch { fields.push({ field: 'body', message: 'Body must be valid JSON.' }); }
    if (!isObject(body)) {
      if (!fields.some((f) => f.field === 'body')) fields.push({ field: 'body', message: 'Body must be a JSON object.' });
    }
    const data = isObject(body) ? body : {};
    const steps = data.steps === undefined ? 5 : data.steps;
    const failAttempts = data.failAttempts === undefined ? 0 : data.failAttempts;
    if (isObject(body)) {
      for (const key of Object.keys(data)) if (!['input', 'steps', 'failAttempts'].includes(key)) fields.push({ field: key, message: 'Unknown field.' });
      if (typeof data.input !== 'string') fields.push({ field: 'input', message: 'Must be a string.' });
      else {
        if (data.input.length < 1 || data.input.length > 1000) fields.push({ field: 'input', message: 'Must be 1 to 1000 characters.' });
        if (!data.input.trim()) fields.push({ field: 'input', message: 'Must not be only whitespace.' });
      }
      if (!Number.isInteger(steps) || (steps as number) < 1 || (steps as number) > 20) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
      if (!Number.isInteger(failAttempts) || (failAttempts as number) < 0 || (failAttempts as number) > 5) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
    }
    const rawKey = req.headers['idempotency-key'];
    if (rawKey !== undefined && (Array.isArray(rawKey) || !/^[A-Za-z0-9_-]{1,128}$/.test(rawKey))) fields.push({ field: 'Idempotency-Key', message: 'Must contain 1 to 128 letters, digits, underscores, or hyphens.' });
    const key = typeof rawKey === 'string' ? rawKey : undefined;
    if (fields.length) return error(res, 400, 'invalid_request', 'The request is invalid.', fields);
    const payload = JSON.stringify({ input: data.input, steps, failAttempts });
    if (key !== undefined) {
      const existing = db.prepare('SELECT payload, job_id FROM idempotency WHERE key = ?').get(key) as { payload: string; job_id: string } | undefined;
      if (existing) {
        if (existing.payload !== payload) return error(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
        const job = getJob(db, existing.job_id);
        if (job) return send(res, 200, job);
      }
    }
    const id = randomUUID(); const now = new Date().toISOString();
    db.exec('BEGIN IMMEDIATE');
    try {
      if (key !== undefined) {
        const existing = db.prepare('SELECT payload, job_id FROM idempotency WHERE key = ?').get(key) as { payload: string; job_id: string } | undefined;
        if (existing) {
          db.exec('COMMIT');
          if (existing.payload !== payload) return error(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
          const job = getJob(db, existing.job_id); if (job) return send(res, 200, job);
        }
      }
      db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,result_output,error,created_at,updated_at,available_at)
        VALUES(?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, 0)`).run(id, data.input as string, steps as number, failAttempts as number, now, now);
      if (key !== undefined) db.prepare('INSERT INTO idempotency(key,payload,job_id) VALUES(?,?,?)').run(key, payload, id);
      db.exec('COMMIT');
    } catch (e) { db.exec('ROLLBACK'); throw e; }
    return send(res, 201, getJob(db, id));
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match && req.method === 'GET') {
    let id: string; try { id = decodeURIComponent(match[1]!); } catch { return error(res, 404, 'not_found', 'Job not found.'); }
    const job = getJob(db, id); return job ? send(res, 200, job) : error(res, 404, 'not_found', 'Job not found.');
  }
  return error(res, 405, 'method_not_allowed', 'Method not allowed.');
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));
function shutdown(): void { server.close(() => { db.close(); process.exit(0); }); }
process.on('SIGTERM', shutdown); process.on('SIGINT', shutdown);

