import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// Recover work left in flight by a dead worker. If this attempt was guaranteed to hit the
// simulated transient failure, record that failure during recovery so restarts cannot bypass the
// three-attempt limit. Other interrupted attempts are immediately eligible for a fresh attempt.
db.exec('BEGIN IMMEDIATE');
try {
  const now = new Date().toISOString();
  db.prepare(`UPDATE jobs SET status='failed', progress_completed=0, result_output=NULL,
    error='transient failure', updated_at=? WHERE status='running' AND attempts >= 3 AND attempts <= fail_attempts`).run(now);
  db.prepare(`UPDATE jobs SET status='queued', progress_completed=0, updated_at=?, available_at=?
    WHERE status='running' AND attempts < 3 AND attempts <= fail_attempts`).run(now, Date.now() + 500);
  db.prepare(`UPDATE jobs SET status='queued', progress_completed=0, updated_at=?, available_at=?
    WHERE status='running'`).run(now, Date.now());
  db.exec('COMMIT');
} catch (e) { db.exec('ROLLBACK'); throw e; }
const heartbeat = () => db.prepare(`INSERT INTO worker_heartbeat(singleton,seen_at) VALUES(1,?)
  ON CONFLICT(singleton) DO UPDATE SET seen_at=excluded.seen_at`).run(Date.now());
heartbeat();
const beatTimer = setInterval(() => { try { heartbeat(); } catch (e) { console.error('heartbeat failed', e); } }, 500);

console.log('worker started');
while (!stopping) {
  let job: { id: string; input: string; steps: number; fail_attempts: number; attempts: number } | undefined;
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db.prepare("SELECT id,input,steps,fail_attempts,attempts FROM jobs WHERE status='queued' AND available_at <= ? ORDER BY created_at ASC, rowid ASC LIMIT 1").get(Date.now()) as typeof job;
    if (row) {
      const attempt = row.attempts + 1;
      db.prepare("UPDATE jobs SET status='running', attempts=?, progress_completed=0, updated_at=? WHERE id=? AND status='queued'")
        .run(attempt, new Date().toISOString(), row.id);
      job = { ...row, attempts: attempt };
    }
    db.exec('COMMIT');
  } catch (e) { db.exec('ROLLBACK'); console.error('queue claim failed', e); }
  if (!job) { await sleep(100); continue; }

  let failed = false;
  if (job.attempts <= job.fail_attempts) {
    // The simulated dependency fails before any step progress is recorded.
    await sleep(100);
    failed = true;
  } else {
    for (let completed = 1; completed <= job.steps && !stopping; completed++) {
      await sleep(100);
      db.prepare("UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running' AND attempts=?")
        .run(completed, new Date().toISOString(), job.id, job.attempts);
    }
    if (stopping) break;
  }
  if (failed) {
    if (job.attempts >= 3) {
      db.prepare("UPDATE jobs SET status='failed', progress_completed=0, result_output=NULL, error='transient failure', updated_at=? WHERE id=? AND status='running' AND attempts=?")
        .run(new Date().toISOString(), job.id, job.attempts);
    } else {
      db.prepare("UPDATE jobs SET status='queued', progress_completed=0, updated_at=?, available_at=? WHERE id=? AND status='running' AND attempts=?")
        .run(new Date().toISOString(), Date.now() + 500, job.id, job.attempts);
    }
  } else {
    db.prepare("UPDATE jobs SET status='completed', progress_completed=steps, result_output=?, error=NULL, updated_at=? WHERE id=? AND status='running' AND attempts=?")
      .run(job.input.toUpperCase(), new Date().toISOString(), job.id, job.attempts);
  }
}

clearInterval(beatTimer);
db.prepare('DELETE FROM worker_heartbeat WHERE singleton = 1').run();
db.close();

